using Xunit;namespace SvcSystems.AI.AgentClientProtocol.IntegrationTests;public sealed class TestyIntegrationTests{    [Fact]    [Trait("Category", "Integration")]    public async Task TestyEchoStreamsAnAgentMessage()    {        var binaries = await TestyBinaryProvider.GetAsync();        if (binaries is null)        {            Assert.Skip("Testy auto-build requires Cargo. Install Rust/Cargo or set ACP_TESTY_BIN.");        }        var testyPath = binaries.TestyPath;        var workingDirectory = Path.Combine(Path.GetTempPath(), "acp-testy-" + Guid.NewGuid().ToString("N"));        Directory.CreateDirectory(workingDirectory);        try        {            using var timeout = new CancellationTokenSource(TimeSpan.FromMinutes(2));            await using var client = await AcpClient.StartAsync(                new ProcessOptions                {                    FileName = testyPath,                    WorkingDirectory = workingDirectory,                    StandardErrorReceived = line => Console.Error.WriteLine("[testy] " + line)                },                cancellationToken: timeout.Token);            Assert.NotNull(client.Agent);            Assert.Equal(1, client.Agent.ProtocolVersion);            var session = await client.CreateSessionAsync(                new SessionOptions { WorkingDirectory = workingDirectory },                timeout.Token);            var updates = new List<SessionEvent>();            await foreach (var update in session.PromptAsync("echo hello from acp client", timeout.Token))            {                updates.Add(update);            }            Assert.Contains(AgentMessageTexts(updates), text => text.Contains("hello from acp client", StringComparison.OrdinalIgnoreCase));            Assert.Contains(updates, update => update is Completed { Response.StopReason: "end_turn" });        }        finally        {            try { Directory.Delete(workingDirectory, recursive: true); }            catch (IOException) { /* the agent process may still be shutting down */ }            catch (UnauthorizedAccessException) { /* best-effort cleanup of a test-owned temp directory */ }        }    }    [Fact]    [Trait("Category", "Integration")]    public async Task TestyWaitForCancelConfirmsPromptCancellation()    {        var binaries = await TestyBinaryProvider.GetAsync();        if (binaries is null)        {            Assert.Skip("Testy auto-build requires Cargo. Install Rust/Cargo or set ACP_TESTY_BIN.");        }        var testyPath = binaries.TestyPath;        var workingDirectory = Path.Combine(Path.GetTempPath(), "acp-testy-cancel-" + Guid.NewGuid().ToString("N"));        Directory.CreateDirectory(workingDirectory);        try        {            using var timeout = new CancellationTokenSource(TimeSpan.FromMinutes(2));            await using var client = await AcpClient.StartAsync(                new ProcessOptions { FileName = testyPath, WorkingDirectory = workingDirectory },                cancellationToken: timeout.Token);            var session = await client.CreateSessionAsync(new SessionOptions { WorkingDirectory = workingDirectory }, timeout.Token);            var promptTask = CollectPromptUpdatesAsync(session, "wait_for_cancel", timeout.Token);            await session.CancelAsync(timeout.Token);            var updates = await promptTask.WaitAsync(timeout.Token);            Assert.Contains(updates, update => update is Completed { Response.StopReason: "cancelled" });            var followUpUpdates = await CollectPromptUpdatesAsync(session, "echo after cancellation", timeout.Token);            Assert.Contains(AgentMessageTexts(followUpUpdates), text => text.Contains("after cancellation", StringComparison.OrdinalIgnoreCase));            Assert.Contains(followUpUpdates, update => update is Completed { Response.StopReason: "end_turn" });        }        finally        {            try { Directory.Delete(workingDirectory, recursive: true); }            catch (IOException) { }            catch (UnauthorizedAccessException) { }        }    }    [Fact]    [Trait("Category", "Integration")]    public async Task OpenCodeHandshakeWorksWhenConfigured()    {        var openCodePath = Environment.GetEnvironmentVariable("ACP_OPENCODE_BIN");        if (string.IsNullOrWhiteSpace(openCodePath) || !File.Exists(openCodePath))        {            Assert.Skip("Set ACP_OPENCODE_BIN to an OpenCode executable to run this optional compatibility check.");        }        var workingDirectory = Path.Combine(Path.GetTempPath(), "acp-opencode-" + Guid.NewGuid().ToString("N"));        Directory.CreateDirectory(workingDirectory);        try        {            using var timeout = new CancellationTokenSource(TimeSpan.FromMinutes(2));            await using var client = await AcpClient.StartAsync(                new ProcessOptions { FileName = openCodePath, Arguments = ["acp"], WorkingDirectory = workingDirectory },                cancellationToken: timeout.Token);            Assert.Equal(1, client.Agent.ProtocolVersion);            Assert.False(string.IsNullOrWhiteSpace(client.Agent.AgentInfo?.Name));        }        finally        {            try { Directory.Delete(workingDirectory, recursive: true); }            catch (IOException) { }            catch (UnauthorizedAccessException) { }        }    }    [Fact]    [Trait("Category", "Integration")]    public async Task TestyCanUseConfiguredStdioMcpServer()    {        var binaries = await TestyBinaryProvider.GetAsync();        if (binaries is null || string.IsNullOrWhiteSpace(binaries.McpEchoPath) || !File.Exists(binaries.McpEchoPath))        {            Assert.Skip("This scenario requires Cargo to build both binaries, or valid ACP_TESTY_BIN and ACP_MCP_ECHO_BIN paths.");        }        var testyPath = binaries.TestyPath;        var mcpEchoPath = binaries.McpEchoPath!;        var workingDirectory = Path.Combine(Path.GetTempPath(), "acp-testy-mcp-" + Guid.NewGuid().ToString("N"));        Directory.CreateDirectory(workingDirectory);        try        {            using var timeout = new CancellationTokenSource(TimeSpan.FromMinutes(2));            await using var client = await AcpClient.StartAsync(                new ProcessOptions { FileName = testyPath, WorkingDirectory = workingDirectory },                cancellationToken: timeout.Token);            var session = await client.CreateSessionAsync(new SessionOptions            {                WorkingDirectory = workingDirectory,                McpServers = [new McpServerStdio { Name = "echo", Command = mcpEchoPath, Args = [], Env = [] }]            }, timeout.Token);            var listUpdates = await CollectPromptUpdatesAsync(                session,                "{\"command\":\"list_tools\",\"server\":\"echo\"}",                timeout.Token);            Assert.Contains(AgentMessageTexts(listUpdates), text => text.Contains("echo", StringComparison.Ordinal));            Assert.Contains(listUpdates, update => update is Completed { Response.StopReason: "end_turn" });            var callUpdates = await CollectPromptUpdatesAsync(                session,                "{\"command\":\"call_tool\",\"server\":\"echo\",\"tool\":\"echo\",\"params\":{\"message\":\"hello from the MCP echo tool\"}}",                timeout.Token);            Assert.Contains(AgentMessageTexts(callUpdates), text => text.Contains("Echo: hello from the MCP echo tool", StringComparison.Ordinal));            Assert.Contains(callUpdates, update => update is Completed { Response.StopReason: "end_turn" });        }        finally        {            try { Directory.Delete(workingDirectory, recursive: true); }            catch (IOException) { }            catch (UnauthorizedAccessException) { }        }    }    [Fact]    [Trait("Category", "Integration")]    public async Task TestyFullExercisesAdvertisedClientCapabilities()    {        var binaries = await TestyBinaryProvider.GetAsync();        if (binaries is null)        {            Assert.Skip("Testy auto-build requires Cargo. Install Rust/Cargo or set ACP_TESTY_BIN.");        }        var testyPath = binaries.TestyPath;        var workingDirectory = Path.Combine(Path.GetTempPath(), "acp-testy-full-" + Guid.NewGuid().ToString("N"));        Directory.CreateDirectory(workingDirectory);        var fileSystem = new SandboxedFileSystemHandler(workingDirectory);        var permissionHandler = new RejectOncePermissionHandler();        var terminalHandler = new DeterministicTerminalHandler();        var elicitationHandler = new DeterministicElicitationHandler();        using var timeout = new CancellationTokenSource(TimeSpan.FromMinutes(3));        try        {            await using var client = await AcpClient.StartAsync(                new ProcessOptions                {                    FileName = testyPath,                    WorkingDirectory = workingDirectory                },                new ClientOptions                {                    PermissionHandler = permissionHandler,                    FileSystemHandler = fileSystem,                    TerminalHandler = terminalHandler,                    ElicitationHandler = elicitationHandler,                    ElicitationCompleted = elicitationHandler.OnCompleted                },                timeout.Token);            await client.AuthenticateAsync("testy-agent-auth", timeout.Token);            var extraDirectory = Path.Combine(workingDirectory, "extra");            Directory.CreateDirectory(extraDirectory);            var sessionOptions = new SessionOptions            {                WorkingDirectory = workingDirectory,                AdditionalDirectories = [extraDirectory]            };            var session = await client.CreateSessionAsync(sessionOptions, timeout.Token);            var loadedSession = await client.LoadSessionAsync(session.Id, sessionOptions, timeout.Token);            Assert.Equal(session.Id, loadedSession.Id);            await session.SetModeAsync("plan", timeout.Token);            await session.SetConfigOptionAsync("verbosity", "verbose", timeout.Token);            Assert.Contains(await client.ListSessionsAsync(workingDirectory, cancellationToken: timeout.Token), listed => listed.SessionId == session.Id);            var resumedSession = await client.ResumeSessionAsync(                session.Id,                new SessionOptions { WorkingDirectory = workingDirectory },                timeout.Token);            Assert.Equal(session.Id, resumedSession.Id);            var updates = new List<SessionEvent>();            await foreach (var update in session.PromptAsync("full", timeout.Token)) updates.Add(update);            var text = AgentMessageTexts(updates).First(message =>                message.Contains("scenario: full", StringComparison.Ordinal));            Assert.Contains("session/request_permission: ok", text, StringComparison.Ordinal);            Assert.Contains("fs/write_text_file: ok", text, StringComparison.Ordinal);            Assert.Contains("fs/read_text_file: ok", text, StringComparison.Ordinal);            Assert.Contains("content: \"written by testy\\n\"", text, StringComparison.Ordinal);            Assert.Contains("terminal/create: ok", text, StringComparison.Ordinal);            Assert.Contains("terminal/output: ok", text, StringComparison.Ordinal);            Assert.Contains("terminal/wait_for_exit: ok", text, StringComparison.Ordinal);            Assert.Contains("terminal/kill: ok", text, StringComparison.Ordinal);            Assert.Contains("terminal/release: ok", text, StringComparison.Ordinal);            Assert.Contains("elicitation/form_session_accept: ok", text, StringComparison.Ordinal);            Assert.Contains("elicitation/url_session_accept: ok", text, StringComparison.Ordinal);            Assert.Contains("elicitation/complete_session_url: sent", text, StringComparison.Ordinal);            Assert.Equal("reject_once", permissionHandler.SelectedOptionId);            Assert.Equal("written by testy\n", await File.ReadAllTextAsync(Path.Combine(workingDirectory, "testy-write.txt"), timeout.Token));            var terminalRequest = Assert.IsType<CreateTerminalRequest>(terminalHandler.CreateRequest);            Assert.Equal(session.Id, terminalRequest.SessionId);            Assert.Equal("printf", terminalRequest.Command);            Assert.Equal("testy terminal\n", Assert.Single(terminalRequest.Args!));            Assert.Equal(workingDirectory, terminalRequest.Cwd);            Assert.Equal("testy-terminal-1", Assert.Single(terminalHandler.OutputRequests).TerminalId);            Assert.Equal("testy-terminal-1", Assert.Single(terminalHandler.WaitRequests).TerminalId);            Assert.Equal("testy-terminal-1", Assert.Single(terminalHandler.KillRequests).TerminalId);            Assert.NotEmpty(terminalHandler.ReleaseRequests);            Assert.All(terminalHandler.ReleaseRequests, request => Assert.Equal("testy-terminal-1", request.TerminalId));            Assert.Equal(5, elicitationHandler.Requests.Count);            Assert.Equal(new[] { "accept", "decline", "cancel", "accept", "decline" }, elicitationHandler.Responses);            Assert.Equal(session.Id, elicitationHandler.Requests[0].SessionId);            Assert.False(string.IsNullOrWhiteSpace(elicitationHandler.Requests[0].ToolCallId));            Assert.Equal("testy-request-form-cancel", elicitationHandler.Requests[2].RequestId);            Assert.Equal("testy-url-session", elicitationHandler.Requests[3].ElicitationId);            Assert.Equal("testy-request-url-decline", elicitationHandler.Requests[4].RequestId);            Assert.Equal("testy-url-session", Assert.Single(elicitationHandler.Completed));            var wireUpdates = SessionUpdates(updates);            Assert.Contains(wireUpdates, update => update.Value is SessionUpdateVariant3ToolCall);            Assert.Contains(wireUpdates, update => update.Value is SessionUpdateVariant5Plan);            Assert.Contains(wireUpdates, update => update.Value is SessionUpdateVariant10UsageUpdate { Used: 128, Size: 4096 });            Assert.Contains(wireUpdates, update => update.Value is SessionUpdateVariant9SessionInfoUpdate { Title: "Testy deterministic session" });            Assert.Contains(wireUpdates, update => update.Value is SessionUpdateVariant6AvailableCommandsUpdate);            Assert.Contains(wireUpdates, update => update.Value is SessionUpdateVariant7CurrentModeUpdate { CurrentModeId: "plan" });            Assert.Contains(wireUpdates, update => update.Value is SessionUpdateVariant8ConfigOptionUpdate);            Assert.Contains(updates, update => update is Completed { Response.StopReason: "end_turn" });            await client.CloseSessionAsync(session.Id, timeout.Token);            var deleteSession = await client.CreateSessionAsync(new SessionOptions { WorkingDirectory = workingDirectory }, timeout.Token);            await client.DeleteSessionAsync(deleteSession.Id, timeout.Token);            Assert.DoesNotContain(                await client.ListSessionsAsync(workingDirectory, cancellationToken: timeout.Token),                listed => listed.SessionId == deleteSession.Id);            await client.LogoutAsync(timeout.Token);        }        finally        {            try { Directory.Delete(workingDirectory, recursive: true); }            catch (IOException) { }            catch (UnauthorizedAccessException) { }        }    }    private static async Task<List<SessionEvent>> CollectPromptUpdatesAsync(        Session session,        string prompt,        CancellationToken cancellationToken)    {        var updates = new List<SessionEvent>();        await foreach (var update in session.PromptAsync(prompt, cancellationToken))        {            updates.Add(update);        }        return updates;    }    private static IEnumerable<SessionUpdate> SessionUpdates(IEnumerable<SessionEvent> updates) =>        updates.OfType<SessionUpdateEvent>().Select(update => update.Update);    private static IEnumerable<string> AgentMessageTexts(IEnumerable<SessionEvent> updates) =>        SessionUpdates(updates)            .Select(update => update.Value)            .OfType<SessionUpdateVariant1AgentMessageChunk>()            .Select(update => Assert.IsType<ContentBlockVariant0Text>(update.Content.Value).Text);    private sealed class RejectOncePermissionHandler : IPermissionHandler    {        public string? SelectedOptionId { get; private set; }        public ValueTask<PermissionDecision> RequestPermissionAsync(RequestPermissionRequest request, CancellationToken cancellationToken = default)        {            var reject = request.Options.First(option => option.Kind == "reject_once");            var selectedOptionId = reject.OptionId;            SelectedOptionId = selectedOptionId;            return ValueTask.FromResult(PermissionDecision.Select(selectedOptionId));        }    }    private sealed class SandboxedFileSystemHandler(string root) : IFileSystemHandler    {        public async ValueTask<string> ReadTextFileAsync(ReadTextFileRequest request, CancellationToken cancellationToken = default)        {            var safePath = ValidatePath(request.Path);            var content = await File.ReadAllTextAsync(safePath, cancellationToken);            var newline = content.Contains("\r\n", StringComparison.Ordinal) ? "\r\n" : "\n";            var lines = content.Split(["\r\n", "\n"], StringSplitOptions.None);            var offset = Math.Max(0, checked((int)(request.Line ?? 1) - 1));            var count = request.Limit is null ? int.MaxValue : checked((int)Math.Min(request.Limit.Value, int.MaxValue));            return string.Join(newline, lines.Skip(offset).Take(count));        }        public async ValueTask WriteTextFileAsync(WriteTextFileRequest request, CancellationToken cancellationToken = default)        {            var safePath = ValidatePath(request.Path);            Directory.CreateDirectory(Path.GetDirectoryName(safePath)!);            await File.WriteAllTextAsync(safePath, request.Content, cancellationToken);        }        private string ValidatePath(string path)        {            var fullPath = Path.GetFullPath(path);            var rootPath = Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;            if (!fullPath.StartsWith(rootPath, OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal))                throw new InvalidOperationException("Testy attempted to access a path outside its isolated workspace.");            return fullPath;        }    }    private sealed class DeterministicTerminalHandler : ITerminalHandler    {        public CreateTerminalRequest? CreateRequest { get; private set; }        public List<TerminalOutputRequest> OutputRequests { get; } = [];        public List<WaitForTerminalExitRequest> WaitRequests { get; } = [];        public List<KillTerminalRequest> KillRequests { get; } = [];        public List<ReleaseTerminalRequest> ReleaseRequests { get; } = [];        public ValueTask<string> CreateAsync(CreateTerminalRequest request, CancellationToken cancellationToken = default)        {            CreateRequest = request;            return ValueTask.FromResult("testy-terminal-1");        }        public ValueTask<TerminalOutputResponse> GetOutputAsync(TerminalOutputRequest request, CancellationToken cancellationToken = default)        {            OutputRequests.Add(request);            return ValueTask.FromResult(new TerminalOutputResponse { Output = "testy terminal\n", Truncated = false, ExitStatus = new TerminalExitStatus { ExitCode = 0 } });        }        public ValueTask<TerminalExitStatus> WaitForExitAsync(WaitForTerminalExitRequest request, CancellationToken cancellationToken = default)        {            WaitRequests.Add(request);            return ValueTask.FromResult(new TerminalExitStatus { ExitCode = 0 });        }        public ValueTask KillAsync(KillTerminalRequest request, CancellationToken cancellationToken = default)        {            KillRequests.Add(request);            return ValueTask.CompletedTask;        }        public ValueTask ReleaseAsync(ReleaseTerminalRequest request, CancellationToken cancellationToken = default)        {            ReleaseRequests.Add(request);            return ValueTask.CompletedTask;        }    }    private sealed class DeterministicElicitationHandler : IElicitationHandler    {        public bool SupportsForm => true;        public bool SupportsUrl => true;        public List<string> Completed { get; } = [];        public List<ElicitationRequest> Requests { get; } = [];        public List<string> Responses { get; } = [];        public ValueTask<ElicitationResponse> RequestElicitationAsync(ElicitationRequest request, CancellationToken cancellationToken = default)        {            Requests.Add(request);            if (request.Message.Contains("Decline", StringComparison.OrdinalIgnoreCase))                return RecordResponse("decline");            if (request.Message.Contains("Cancel", StringComparison.OrdinalIgnoreCase))                return RecordResponse("cancel");            if (request.Mode == "form" && request.RequestedSchema is { } schema)                return RecordResponse("accept", CreateFormAnswer(schema));            return RecordResponse("accept");        }        public void OnCompleted(ElicitationCompleted notification) => Completed.Add(notification.ElicitationId);        private ValueTask<ElicitationResponse> RecordResponse(string action, IReadOnlyDictionary<string, ElicitationContentValue>? content = null)        {            Responses.Add(action);            return ValueTask.FromResult(new ElicitationResponse(action, content));        }        private static IReadOnlyDictionary<string, ElicitationContentValue> CreateFormAnswer(ElicitationSchema schema)        {            var answer = new Dictionary<string, ElicitationContentValue>(StringComparer.Ordinal);            if (schema.Required is not null && schema.Properties is not null)            {                foreach (var field in schema.Required)                {                    if (!schema.Properties.TryGetValue(field, out var definition)) continue;                    switch (definition)                    {                        case StringPropertySchema: answer[field] = "testy"; break;                        case NumberPropertySchema: answer[field] = 0.5; break;                        case IntegerPropertySchema: answer[field] = 42L; break;                        case BooleanPropertySchema: answer[field] = true; break;                        case MultiSelectPropertySchema: answer[field] = new List<string>(); break;                    }                }            }            return answer;        }    }}